INSERT INTO `tblcategory` (`id`, `CategoryName`, `Description`, `PostingDate`, `UpdationDate`, `Is_Active`) VALUES
(3, 'မျက်စိကျန်းမာရေး', 'မျက်စိနှင့်သက်ဆိုင်သောအကြောင်းအရာများ', '2021-06-05 18:30:00', '2024-02-08 11:16:03', 1),
(5, 'နား၊ နှာခေါင်း၊ လည်ချောင်း', ' နား၊ နှာခေါင်း၊ လည်ချောင်း ရောဂါများနဲ့ ပတ်သက်ပြီး သတိထားရမယ့် အချက်တွေ၊ ဆောင်ရန်၊ ရှောင်ရန်တွေကို ဖတ်ရှုနိုင်ပါတယ်။', '2021-06-13 18:30:00', '2024-02-08 15:17:38', 1),
(6, 'ဆီးချို သွေးချို', 'ဆီးချိုဆိုတာ အလွန် ကြောက်စရာကောင်းပြီး အဖြစ်များလှတဲ့ ရောဂါတစ်ခုပါ။', '2021-06-21 18:30:00', '2024-02-08 16:23:53', 1),
(7, 'သွေးရောဂါများ', 'သွေးရောဂါတွေလို့ ဆိုလိုက်ရင် သွေးနီဥ၊ သွေးဖြူဥ၊ သွေးရည်ကြည်နဲ့ သွေးဥမွှားပြဿနာတွေ ပါဝင်ပါတယ်။', '2021-06-21 18:30:00', '2024-02-08 16:24:57', 1),
(8, 'နှလုံးနှင့်သွေးကြော ကျန်းမာရေး', 'သွေးလည်ပတ်မှု သွေးပို့ဆောင်မှုတွေ အဟန့်အတားဖြစ်တာ၊ ထိခိုက်တာတွေက ပြင်းထန်တဲ့ ကျန်းမာရေး ပြဿနာတွေကို ဖြစ်စေနိုင်ပါတယ်။', '2021-11-07 18:17:28', '2024-02-08 16:26:56', 1),
(9, 'အိပ်စက်ခြင်း', 'ကျန်းမာရေးဗဟုသုတ', '2024-02-08 12:45:14', NULL, 1),
(10, 'အသက်ရှူလမ်းကြောင်းကျန်းမာရေး', 'အသက်ရှူလမ်းကြောင်းစနစ်က ခန္ဓာကိုယ်ရဲ့ အရေးပါတဲ့ လုပ်ငန်းဆောင်တာတွေကို လုပ်ဆောင်နိုင်စေဖို့ ထောက်ကူပေးပါတယ်။', '2024-02-08 16:28:15', NULL, 1),
(11, 'ကင်ဆာရောဂါများ', 'ကင်ဆာ ဖြစ်စေနိုင်တဲ့ အရာတွေ၊ ကင်ဆာဖြစ်စေတဲ့ အကြောင်းအရင်းတွေ၊ လက္ခဏာတွေ၊ စစ်ဆေး အဖြေရှာနည်းတွေ၊ ကုထုံးတွေ၊ ကာကွယ်နည်းတွေကို သိထားဖို့ လိုပါမယ်။', '2024-02-08 16:29:23', NULL, 1),
(12, 'ဦးနှောက်အာရုံကြောကျန်းမာရေး', ' ဦးနှောက်နဲ့ အာရုံကြောကို ထိခိုက်စေနိုင်တဲ့ ရောဂါတွေ၊ ကုသနည်းတွေနဲ့ ကာကွယ်နည်းတွေကို လေ့လာနိုင်ပါတယ်။', '2024-02-08 16:30:13', NULL, 1),
(13, 'အစာအိမ်နှင့်အူလမ်းကြောင်း ကျန်းမာရေး', 'ခန္ဓာကိုယ်မှာ အစာအိမ်နဲ့ အူလမ်းကြောင်းစနစ်က အရေးပါတဲ့ စနစ်တစ်ခုပါ။ စားလိုက်သမျှ အစားအစာတွေကနေ အာဟာရစုပ်ယူဖို့ဆိုတာ အစာအိမ်နဲ့ အူလမ်းကြောင်းက လုပ်ပေးမှ ရတာပါ။ ဒီလိုစုပ်ယူနိုင်ဖို့ အစာအိမ်နဲ့ အူလမ်းကြောင်း တလျှောက်မှာရှိတဲ့ အင်္ဂါအစိတ်အပိုင်းတွေ အတူတကွ အလုပ်လုပ်ဖို့ လိုပါတယ်။', '2024-02-08 16:31:46', NULL, 1),
(14, 'အရိုးအဆစ်နဲ့ကြွက်သားကျန်းမာရေး', 'အရိုးအဆစ်နဲ့ ကြွက်သားတွေ ကျန်းမာစေဖို့', '2024-02-08 16:32:31', NULL, 1),
(15, 'ဆီးနှင့်ကျောက်ကပ်ကျန်းမာရေး', ' ဆီးနဲ့ ကျောက်ကပ်ကျန်းမာနေဖို့ဆိုရင် သူ့မှာပါတဲ့ ကျောက်ကပ်၊ ဆီးပို့ပြွန်၊ ဆီးလွှတ်ပြွန်၊ ဆီးအိမ်တွေ ကောင်းကောင်း အလုပ်လုပ်နိုင်ဖို့ လိုပါတယ်။', '2024-02-08 16:33:16', NULL, 1),
(16, 'ကူးစက်ရောဂါများ', 'အဖြစ်များတဲ့ ကူးစက်ရောဂါတွေအကြောင်း', '2024-02-08 16:35:56', NULL, 1),
(17, 'ဆေးလိပ်ဖြတ်ခြင်း', 'ကျန်းမာရေးဗဟုသုတ', '2024-02-09 06:38:05', NULL, 1);

